        all_slugs.append((level, title, slug))

    # Count occurrences of each slug to determine suffixes
    slug_counts: Dict[str, int] = {}
    slug_occurrence: Dict[int, int] = {}  # maps index in all_slugs to occurrence number
    for i, (level, title, slug) in enumerate(all_slugs):
        if slug == "":
            slug_occurrence[i] = -1  # will be filtered
            continue
        if slug not in slug_counts:
            slug_counts[slug] = 0
        slug_occurrence[i] = slug_counts[slug]
        slug_counts[slug] += 1

    # Filter by max_level and empty slug
    filtered: List[Tuple[int, str, str, int]] = []
    for i, (level, title, slug) in enumerate(all_slugs):
        if level > max_level:
            continue
        if slug == "":
            continue
        occurrence = slug_occurrence[i]
        filtered.append((level, title, slug, occurrence))

    if not filtered:
        return ""

    # Find the shallowest level
    min_level = min(item[0] for item in filtered)

    # Build lines
    lines: List[str] = []
